package com.infernalvariants;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import java.util.WeakHashMap;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.TextureProvider;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.PostItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Infernal Variants",
	description = "Custom infernal cape designs (Holy, Ice, Dragonfire, Rune, Void and more) with animated veins",
	tags = {"infernal", "cape", "cosmetic", "recolor", "recolour", "fire", "inferno"}
)
public class InfernalVariantsPlugin extends Plugin
{
	/** The game's own infernal cape lava texture. */
	static final int INFERNAL_TEXTURE = 59;

	private static final int[] CAPE_IDS = {
		ItemID.INFERNAL_CAPE,
		ItemID.BR_INFERNAL_CAPE,
		ItemID.INFERNAL_CAPE_TROUVER,
		ItemID.INFERNAL_CAPE_TROUVER_BROKEN,
		ItemID.INFERNAL_CAPE_TROUVER_MANGLED,
	};

	private static final int MAX_CAPE_ID = ItemID.SKILLCAPE_MAX_INFERNALCAPE;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CapeOverlay overlay;

	@Inject
	private InfernalVariantsConfig config;

	@Inject
	private ConfigManager configManager;

	/** The game's own crack pattern as a heat map; every other pattern is generated. */
	private float[] crackHeat;
	private CapeTextures.Analysis analysis;
	private final Map<CapePattern, CapeTextures.Analysis> analyses = new EnumMap<>(CapePattern.class);
	private final Map<CapeStyle, BufferedImage> veinTextures = new EnumMap<>(CapeStyle.class);
	private final Map<CapeStyle, BufferedImage> hemTextures = new EnumMap<>(CapeStyle.class);
	private final Map<CapeStyle, BufferedImage> glowTextures = new EnumMap<>(CapeStyle.class);
	private final Map<CapeStyle, StyleLook> looks = new EnumMap<>(CapeStyle.class);
	private final Map<CapeStyle, BufferedImage[]> emblemSprites = new EnumMap<>(CapeStyle.class);

	/** Players whose cape we've put a colour override on, and the style it carries. */
	private final Map<Player, CapeStyle> applied = new WeakHashMap<>();
	/** Hides the real lava panel while each frame is drawn, so only the repainted design shows. */
	private final PanelHider hider = new PanelHider();

	@Provides
	InfernalVariantsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InfernalVariantsConfig.class);
	}

	@Override
	protected void startUp()
	{
		applyCustom();
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			// re-load the cape item definitions so our recolour hook sees them
			client.getItemCompositionCache().reset();
			loadHeat();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.reset();
		clientThread.invoke(() ->
		{
			hider.restore();
			for (Map.Entry<Player, CapeStyle> e : applied.entrySet())
			{
				removeOverride(e.getKey());
			}
			applied.clear();
			client.getItemCompositionCache().reset();
		});
		veinTextures.clear();
		hemTextures.clear();
		emblemSprites.clear();
		analysis = null;
		crackHeat = null;
		analyses.clear();
		glowTextures.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!InfernalVariantsConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		// colours are re-applied on the next client tick
		if (e.getKey() != null && e.getKey().startsWith("custom"))
		{
			applyCustom();
		}
		overlay.reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			applied.clear();
			overlay.reset();
		}
	}

	@Subscribe
	public void onPostItemComposition(PostItemComposition e)
	{
		ItemComposition item = e.getItemComposition();
		if (!isInfernal(item.getId()))
		{
			return;
		}
		// Register the cape's model colours as recolourable (mapped to themselves), so a per-player
		// colour override can repaint them. On its own this changes nothing visually.
		item.setColorToReplace(InfernalColors.ALL.clone());
		item.setColorToReplaceWith(InfernalColors.ALL.clone());
	}

	/**
	 * Just before the scene is drawn: hide the lava panel of every cape we repaint, so it can't show
	 * through the design. The overlay puts it back once it has painted the design (see
	 * {@link #restorePanels()}); anything left over is put back here first.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender e)
	{
		hider.restore();
		if (!texturesReady())
		{
			return;
		}
		try
		{
			Player local = client.getLocalPlayer();
			for (Player p : client.getTopLevelWorldView().players())
			{
				if (p == null || (p != local && config.others() == InfernalVariantsConfig.OthersMode.OFF))
				{
					continue;
				}
				CapeStyle style = styleFor(p);
				if (style != null && !style.isOriginal() && !onPetMount(p))
				{
					hider.hide(p.getModel());
				}
			}
		}
		catch (RuntimeException ex)
		{
			hider.restore(); // never leave a cape half hidden
		}
	}

	/**
	 * Whether the Pet Mounts plugin is drawing this player up on a mount. It hides the real player then and draws
	 * a copy of them in the saddle, so a design painted where the real player stands would float beside the
	 * mount. Those capes are left as the game draws them (on the rider) instead.
	 */
	boolean onPetMount(Player p)
	{
		if ("false".equals(configManager.getConfiguration("runelite", "petmountsplugin")))
		{
			return false; // Pet Mounts switched off
		}
		if (p == client.getLocalPlayer())
		{
			return "true".equals(configManager.getConfiguration("petmounts", "wasMounted"));
		}
		if (!"true".equals(configManager.getConfiguration("petmounts", "everyoneRides")))
		{
			return false;
		}
		// Other players ride when their pet is following them.
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc != null && npc.getInteracting() == p)
			{
				NPCComposition comp = npc.getComposition();
				if (comp != null && comp.isFollower())
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Puts the lava panels back once the frame is drawn. */
	void restorePanels()
	{
		hider.restore();
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		if (analysis == null)
		{
			loadHeat();
		}

		for (Player p : client.getTopLevelWorldView().players())
		{
			if (p == null)
			{
				continue;
			}
			CapeStyle want = styleFor(p);
			CapeStyle have = applied.get(p);
			if (want == null || want.isOriginal())
			{
				if (have != null)
				{
					removeOverride(p);
					applied.remove(p);
				}
				continue;
			}
			applyOverride(p, want);
		}
	}

	private void applyOverride(Player p, CapeStyle style)
	{
		PlayerComposition pc = p.getPlayerComposition();
		if (pc == null)
		{
			return;
		}
		int itemId = pc.getEquipmentId(KitType.CAPE);
		ColorTextureOverride ov = pc.getColorTextureOverride(KitType.CAPE);
		if (ov == null)
		{
			ov = pc.createColorTextureOverride(KitType.CAPE, itemId);
		}
		if (ov == null)
		{
			return;
		}
		short[] with = ov.getColorToReplaceWith();
		if (with == null || with.length != InfernalColors.ALL.length)
		{
			// item definition was cached before our hook ran; it will be reloaded shortly
			return;
		}
		boolean changed = false;
		for (int i = 0; i < with.length; i++)
		{
			short c = CapeTextures.mapColor(style, InfernalColors.ALL[i]);
			if (with[i] != c)
			{
				with[i] = c;
				changed = true;
			}
		}
		if (changed)
		{
			pc.setHash();
		}
		applied.put(p, style);
	}

	private void removeOverride(Player p)
	{
		PlayerComposition pc = p.getPlayerComposition();
		if (pc != null && pc.getColorTextureOverride(KitType.CAPE) != null)
		{
			pc.removeColorTextureOverride(KitType.CAPE);
			pc.setHash();
		}
	}

	/** The style a player's cape should show, or null if they aren't wearing an infernal cape we handle. */
	CapeStyle styleFor(Player p)
	{
		PlayerComposition pc = p.getPlayerComposition();
		if (pc == null)
		{
			return null;
		}
		int itemId = pc.getEquipmentId(KitType.CAPE);
		if (!isInfernal(itemId) || (itemId == MAX_CAPE_ID && !config.maxCape()))
		{
			return null;
		}
		if (p == client.getLocalPlayer())
		{
			return config.style();
		}
		switch (config.others())
		{
			case SAME:
				return config.style();
			case RANDOM:
			{
				String name = p.getName();
				CapeStyle[] all = CapeStyle.values();
				int h = name == null ? 0 : (name.hashCode() & 0x7FFFFFFF);
				// any designed style; never the original or the custom one
				return all[1 + h % (all.length - 2)];
			}
			default:
				return null;
		}
	}

	static boolean isInfernal(int itemId)
	{
		if (itemId == MAX_CAPE_ID)
		{
			return true;
		}
		for (int id : CAPE_IDS)
		{
			if (id == itemId)
			{
				return true;
			}
		}
		return false;
	}

	boolean isMaxCape(Player p)
	{
		PlayerComposition pc = p.getPlayerComposition();
		return pc != null && pc.getEquipmentId(KitType.CAPE) == MAX_CAPE_ID;
	}

	/** Copy the custom colours from the config into the Custom style and drop its cached art. */
	private void applyCustom()
	{
		CapeStyle c = CapeStyle.CUSTOM;
		int plate = config.customPlate().getRGB() & 0xFFFFFF;
		int vein = config.customVein().getRGB() & 0xFFFFFF;
		int core = config.customCore().getRGB() & 0xFFFFFF;
		c.stopRgb[0] = plate;
		c.stopRgb[1] = CapeTextures.lerp(plate, vein, 0.35f);
		c.stopRgb[2] = vein;
		c.stopRgb[3] = core;
		CapeStyle.customBase = config.customBase();
		veinTextures.remove(c);

		float[] p = java.awt.Color.RGBtoHSB((plate >> 16) & 255, (plate >> 8) & 255, plate & 255, null);
		c.rockHue = Math.round(p[0] * 64) & 63;
		c.rockSat = Math.round(p[1] * 4);
		c.rockLightShift = Math.round(p[2] * 40);
		float[] v = java.awt.Color.RGBtoHSB((vein >> 16) & 255, (vein >> 8) & 255, vein & 255, null);
		c.glowHue = Math.round(v[0] * 64) & 63;
		c.glowSat = Math.round(v[1] * 7);

		veinTextures.remove(c);
		hemTextures.remove(c);
		glowTextures.remove(c);
		boltFrames.remove(c);
		looks.remove(c);
		emblemGlows.remove(c);
		emblemSprites.remove(c);
	}

	private void loadHeat()
	{
		TextureProvider tp = client.getTextureProvider();
		if (tp == null)
		{
			return;
		}
		int[] pixels = tp.load(INFERNAL_TEXTURE);
		if (pixels == null || pixels.length < CapeTextures.SIZE * CapeTextures.SIZE)
		{
			return;
		}
		crackHeat = CapeTextures.heatMap(pixels, tp.getBrightness());
		analyses.clear();
		analysis = analysisFor(CapePattern.CRACKS);
		glowTextures.clear();
		veinTextures.clear();
		hemTextures.clear();
		emblemSprites.clear();
	}

	private CapeTextures.Analysis analysisFor(CapePattern pattern)
	{
		return analyses.computeIfAbsent(pattern, pt -> new CapeTextures.Analysis(pt.heat(crackHeat)));
	}

	boolean texturesReady()
	{
		return analysis != null;
	}

	BufferedImage veinTexture(CapeStyle style)
	{
		if (analysis == null || style.isOriginal())
		{
			return null;
		}
		return veinTextures.computeIfAbsent(style, s -> CapeTextures.veinTexture(s, analysisFor(s.pattern())));
	}

	BufferedImage hemTexture(CapeStyle style)
	{
		if (analysis == null || !CapeTextures.hasHem(style))
		{
			return null;
		}
		return hemTextures.computeIfAbsent(style, s -> CapeTextures.hemTexture(s, analysisFor(s.pattern())));
	}

	BufferedImage glowTexture(CapeStyle style)
	{
		if (analysis == null || style.isOriginal())
		{
			return null;
		}
		return glowTextures.computeIfAbsent(style, s -> CapeTextures.glowTexture(s, analysisFor(s.pattern())));
	}

	private final Map<CapeStyle, BufferedImage> emblemGlows = new EnumMap<>(CapeStyle.class);

	BufferedImage emblemGlow(CapeStyle style)
	{
		return emblemGlows.computeIfAbsent(style, CapeTextures::glowSprite);
	}

	private final Map<CapeStyle, BufferedImage[]> boltFrames = new EnumMap<>(CapeStyle.class);

	/** Lightning bolt frames for styles that use the storm pattern, otherwise null. */
	BufferedImage[] boltFrames(CapeStyle style)
	{
		if (analysis == null || style.pattern() != CapePattern.STORM)
		{
			return null;
		}
		return boltFrames.computeIfAbsent(style, s -> CapeTextures.boltFrames(s, analysisFor(s.pattern())));
	}

	StyleLook look(CapeStyle style)
	{
		return looks.computeIfAbsent(style, StyleLook::of);
	}

	BufferedImage[] emblems(CapeStyle style)
	{
		return emblemSprites.computeIfAbsent(style, s ->
		{
			BufferedImage[] arr = new BufferedImage[4];
			for (int i = 0; i < arr.length; i++)
			{
				arr[i] = CapeTextures.emblemSprite(s.emblem(), i, s);
			}
			return arr;
		});
	}

	InfernalVariantsConfig getConfig()
	{
		return config;
	}
}

package com.infernalvariants;

import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.WeakHashMap;

/**
 * Smaller copies of each cape texture (half, quarter, eighth size), each pixel the average of the four
 * below it. When the cape is small on screen (zoomed out, or far away) the matching copy is drawn, so
 * the design keeps its look instead of breaking up into flickering, jagged pixels.
 */
final class Mips
{
	/** Smallest copy kept, in pixels across. */
	private static final int MIN_SIZE = 8;

	private final Map<BufferedImage, BufferedImage[]> cache = new WeakHashMap<>();

	/** The texture and its smaller copies, largest first. */
	BufferedImage[] of(BufferedImage image)
	{
		if (image == null)
		{
			return null;
		}
		return cache.computeIfAbsent(image, Mips::build);
	}

	void clear()
	{
		cache.clear();
	}

	/**
	 * Which copy to draw for a triangle covering this many texture pixels and this many screen pixels:
	 * about one texture pixel per screen pixel.
	 */
	static int level(float texArea, float screenArea, int levels)
	{
		if (screenArea <= 0 || texArea <= 0)
		{
			return levels - 1;
		}
		double texelsPerPixel = Math.sqrt(texArea / screenArea);
		int level = texelsPerPixel <= 1 ? 0 : (int) Math.floor(Math.log(texelsPerPixel) / Math.log(2));
		return Math.max(0, Math.min(levels - 1, level));
	}

	static BufferedImage[] build(BufferedImage image)
	{
		java.util.List<BufferedImage> out = new java.util.ArrayList<>();
		out.add(image);
		BufferedImage cur = image;
		while (cur.getWidth() / 2 >= MIN_SIZE && cur.getHeight() / 2 >= MIN_SIZE)
		{
			cur = half(cur);
			out.add(cur);
		}
		return out.toArray(new BufferedImage[0]);
	}

	/** Half the size: each pixel averages a 2x2 block, weighted by alpha so glows don't darken at the edges. */
	static BufferedImage half(BufferedImage src)
	{
		int w = src.getWidth() / 2, h = src.getHeight() / 2;
		BufferedImage dst = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int a = 0, r = 0, g = 0, b = 0;
				for (int dy = 0; dy < 2; dy++)
				{
					for (int dx = 0; dx < 2; dx++)
					{
						int p = src.getRGB(2 * x + dx, 2 * y + dy);
						int pa = p >>> 24;
						a += pa;
						r += ((p >> 16) & 0xFF) * pa;
						g += ((p >> 8) & 0xFF) * pa;
						b += (p & 0xFF) * pa;
					}
				}
				int argb = 0;
				if (a > 0)
				{
					argb = ((a / 4) << 24) | ((r / a) << 16) | ((g / a) << 8) | (b / a);
				}
				dst.setRGB(x, y, argb);
			}
		}
		return dst;
	}
}

package com.infernalvariants;

import net.runelite.api.Model;

/**
 * Hides the real lava panel of a cape for one frame, so only the repainted design shows.
 * <p>
 * The design is painted over the scene after it is drawn. Painting over the lava panel left it
 * showing through wherever the two didn't line up exactly (a frame of animation apart, or a
 * triangle the paint skipped). Instead, just before each frame is drawn the panel's faces are
 * marked hidden (the game skips any face whose third colour is -2, in both the normal and the GPU
 * renderer), and they are put back as soon as the frame is done. The player's model in the game's
 * cache is never left changed: if anything goes wrong, the next frame restores it first.
 */
final class PanelHider
{
	private static final int HIDDEN = -2;

	/** Every colour array changed this frame, with the face and the colour it had. */
	private int[][] arrays = new int[16][];
	private int[] faces = new int[16];
	private int[] colors = new int[16];
	private int count;

	/** Hides every lava-textured face of this model until {@link #restore()}. */
	void hide(Model model)
	{
		if (model == null)
		{
			return;
		}
		short[] textures = model.getFaceTextures();
		int[] colors3 = model.getFaceColors3();
		if (textures == null || colors3 == null)
		{
			return;
		}
		int n = Math.min(model.getFaceCount(), Math.min(textures.length, colors3.length));
		for (int f = 0; f < n; f++)
		{
			if (textures[f] == InfernalVariantsPlugin.INFERNAL_TEXTURE && colors3[f] != HIDDEN)
			{
				remember(colors3, f);
				colors3[f] = HIDDEN;
			}
		}
	}

	/** Puts back every face hidden since the last restore. */
	void restore()
	{
		for (int i = count - 1; i >= 0; i--)
		{
			int[] a = arrays[i];
			if (faces[i] < a.length && a[faces[i]] == HIDDEN)
			{
				a[faces[i]] = colors[i];
			}
			arrays[i] = null;
		}
		count = 0;
	}

	boolean isHiding()
	{
		return count > 0;
	}

	private void remember(int[] array, int face)
	{
		if (count == arrays.length)
		{
			arrays = java.util.Arrays.copyOf(arrays, count * 2);
			faces = java.util.Arrays.copyOf(faces, count * 2);
			colors = java.util.Arrays.copyOf(colors, count * 2);
		}
		arrays[count] = array;
		faces[count] = face;
		colors[count] = array[face];
		count++;
	}
}

package com.infernalvariants;

/**
 * The finer art direction for each style: the colour that bleeds out of the veins onto the
 * stone (so veins read as two-tone and glowing rather than flat), how much the individual
 * stone plates vary, and how the cape moves.
 */
final class StyleLook
{
	enum Motion
	{
		/** Steady downward flow with a gentle glow breath. */
		FLOW,
		/** Glow swells and fades on a slow cycle. */
		PULSE,
		/** Irregular electric flicker with sudden surges. */
		FLICKER,
		/** A band of light sweeps down the cape. */
		SHIMMER,
		/** Several soft waves travel down the cape. */
		RIPPLE,
		/** Uneven firelight flicker, brighter toward the hem. */
		BURN,
	}

	/** Colour of the glow that spills from the veins onto the plates (RGB). */
	final int halo;
	/** 0-1: how strongly that glow spills. */
	final float haloStrength;
	/** 0-1: how much individual plates differ in shade. */
	final float plateVariation;
	final Motion motion;
	/** How fast the veins flow down the cape, in texels per second. */
	final float flowSpeed;
	/** Glow layer opacity range and cycle length. */
	final float glowMin, glowMax, period;

	private StyleLook(int halo, float haloStrength, float plateVariation, Motion motion, float flowSpeed,
		float glowMin, float glowMax, float period)
	{
		this.halo = halo;
		this.haloStrength = haloStrength;
		this.plateVariation = plateVariation;
		this.motion = motion;
		this.flowSpeed = flowSpeed;
		this.glowMin = glowMin;
		this.glowMax = glowMax;
		this.period = period;
	}

	StyleLook withHalo(int newHalo)
	{
		return new StyleLook(newHalo, haloStrength, plateVariation, motion, flowSpeed, glowMin, glowMax, period);
	}

	static StyleLook of(CapeStyle s)
	{
		switch (s)
		{
			case HOLY:
				return new StyleLook(0xFFF2C8, 0.45f, 0.10f, Motion.SHIMMER, 10, 0.05f, 0.75f, 4.5f);
			case SHADOW:
				return new StyleLook(0x5A1E96, 0.55f, 0.18f, Motion.PULSE, 8, 0.0f, 0.55f, 4.0f);
			case ICE:
				return new StyleLook(0x2E6CC0, 0.50f, 0.20f, Motion.SHIMMER, 6, 0.0f, 0.6f, 6.0f);
			case BLOOD:
				return new StyleLook(0x6A0408, 0.60f, 0.18f, Motion.FLOW, 18, 0.1f, 0.45f, 2.2f);
			case NATURE:
				return new StyleLook(0x2E6A18, 0.45f, 0.28f, Motion.PULSE, 7, 0.05f, 0.45f, 5.0f);
			case LIGHTNING:
				return new StyleLook(0xA88A10, 0.40f, 0.14f, Motion.FLICKER, 22, 0.0f, 0.95f, 0.9f);
			case RUNE:
				return new StyleLook(0x0C4E8A, 0.65f, 0.16f, Motion.RIPPLE, 12, 0.05f, 0.7f, 3.0f);
			case VOID:
				return new StyleLook(0x8A1E8A, 0.55f, 0.14f, Motion.PULSE, 8, 0.0f, 0.65f, 3.2f);
			case SANDSTONE:
				return new StyleLook(0x3A2816, 0.30f, 0.34f, Motion.FLOW, 5, 0.0f, 0.0f, 1f);
			case CRYSTAL:
				return new StyleLook(0xC8F0FF, 0.45f, 0.24f, Motion.SHIMMER, 8, 0.05f, 0.8f, 3.5f);
			case CORRUPTED:
				return new StyleLook(0x8A1426, 0.60f, 0.30f, Motion.FLICKER, 10, 0.05f, 0.7f, 2.4f);
			case SANGUINE:
				return new StyleLook(0x8A0A10, 0.70f, 0.16f, Motion.PULSE, 12, 0.1f, 0.65f, 2.6f);
			case AMASCUT:
				return new StyleLook(0xFFD27A, 0.35f, 0.30f, Motion.SHIMMER, 7, 0.0f, 0.7f, 5.0f);
			case GUTHIX:
				return new StyleLook(0x3C5A1A, 0.40f, 0.30f, Motion.PULSE, 6, 0.05f, 0.45f, 6.0f);
			case TORMENTED:
				return new StyleLook(0x1E5A0A, 0.70f, 0.16f, Motion.BURN, 20, 0.15f, 0.8f, 1.0f);
			case VARLAMORE:
				return new StyleLook(0x9A2A1A, 0.60f, 0.18f, Motion.BURN, 12, 0.1f, 0.6f, 1.6f);
			case CUSTOM:
			{
				// borrow the base design's motion and finish, with a halo in the custom colours
				CapeStyle base = CapeStyle.customBase;
				StyleLook b = base == null || base == CapeStyle.CUSTOM || base == CapeStyle.INFERNAL
					? new StyleLook(0, 0.55f, 0.18f, Motion.FLOW, 12, 0.1f, 0.55f, 2.5f)
					: of(base);
				return b.withHalo(CapeTextures.lerp(s.stopRgb[0], s.stopRgb[2], 0.55f));
			}
			default:
				return new StyleLook(0xA02008, 0.5f, 0.15f, Motion.FLOW, 50, 0f, 0f, 1f);
		}
	}

	/**
	 * Glow layer opacity at time {@code t} (seconds) for a face at {@code hemness}
	 * (0 = collar, 1 = hem). {@code seed} varies per face so flicker isn't uniform.
	 */
	float glowAlpha(float t, float hemness, float seed)
	{
		float span = glowMax - glowMin;
		float a;
		switch (motion)
		{
			case PULSE:
			{
				float w = (float) (0.5 + 0.5 * Math.sin(t * 2 * Math.PI / period + hemness * 1.2));
				a = glowMin + span * w * w;
				break;
			}
			case FLICKER:
			{
				// layered fast sines give an irregular crackle, with an occasional full surge
				double n = Math.sin(t * 23.0 + seed * 7.0) * Math.sin(t * 9.0 + seed * 3.0) * Math.sin(t * 3.1 + seed);
				float w = (float) Math.max(0, n) * 1.6f;
				float surge = (float) Math.pow(Math.max(0, Math.sin(t * 2 * Math.PI / period)), 24);
				a = glowMin + span * Math.min(1f, w + surge);
				break;
			}
			case SHIMMER:
			{
				// a soft band travels from collar to hem, then pauses before the next pass
				float phase = (t % period) / period * 1.6f - 0.3f;
				float d = hemness - phase;
				float w = (float) Math.exp(-d * d / 0.018);
				a = glowMin + span * w;
				break;
			}
			case RIPPLE:
			{
				float w = (float) (0.5 + 0.5 * Math.sin(hemness * 11.0 - t * 2 * Math.PI / period));
				a = glowMin + span * w * w * w;
				break;
			}
			case BURN:
			{
				double n = 0.5 + 0.25 * Math.sin(t * 11.0 + seed * 5.0) + 0.25 * Math.sin(t * 17.0 + seed * 2.0);
				a = glowMin + span * (float) n * (0.55f + 0.45f * hemness);
				break;
			}
			case FLOW:
			default:
			{
				float w = (float) (0.5 + 0.5 * Math.sin(t * 2 * Math.PI / period + seed));
				a = glowMin + span * w;
				break;
			}
		}
		return Math.max(0f, Math.min(1f, a));
	}
}

